85	export interface AxisLabelsComputingContext {
86	    // PENDING: ugly impl, refactor for better code structure?
87	    out: {
88	        // - If `noPxChangeTryDetermine` is not empty, it indicates that the result is not reusable
89	        //  when axis pixel extent or axis origin point changed.
90	        //  Generally the result is reusable if the result values are calculated with no dependency
91	        //  on pixel info, such as `axis.dataToCoord` or `axis.extent`.
92	        // - If ensuring no px changed, calling `noPxChangeTryDetermine` to attempt to convert the
93	        //  "estimate" result to "determine" result.
94	        //  If return any falsy, cannot make that conversion and need recompute.
95	        noPxChangeTryDetermine: (() => boolean)[]
96	    }
97	    // Must never be NullUndefined
98	    kind: AxisTickLabelComputingKind
99	}
