176	function makeCategoryLabels(axis: Axis, ctx: AxisLabelsComputingContext): ReturnType<typeof createAxisLabels> {
177	    const labelModel = axis.getLabelModel();
178	    const result = makeCategoryLabelsActually(axis, labelModel, ctx);
179	
180	    return (!labelModel.get('show') || axis.scale.isBlank())
181	        ? {labels: []}
182	        : result;
183	}
