323	function makeAutoCategoryInterval(axis: Axis, ctx: AxisLabelsComputingContext): number {
324	    if (ctx.kind === AxisTickLabelComputingKind.estimate) {
325	        // Currently axisTick is not involved in estimate kind, and the result likely varies during a
326	        // single pass of ec main process, due to the change of axisExtent. Therefore no cache is used.
327	        const result = axis.calculateCategoryInterval(ctx);
328	        ctx.out.noPxChangeTryDetermine.push(function () {
329	            axisInner(axis).autoInterval = result;
330	            return true;
331	        });
332	        return result;
333	    }
334	    // Both tick and label uses this result, cacah it to avoid recompute.
335	    const result = axisInner(axis).autoInterval;
336	    return result != null
337	        ? result
338	        : (axisInner(axis).autoInterval = axis.calculateCategoryInterval(ctx));
339	}
340	
341	/**
342	 * Calculate interval for category axis ticks and labels.
343	 * Use a stretegy to try to avoid overlapping.
344	 * To get precise result, at least one of `getRotate` and `isHorizontal`
345	 * should be implemented in axis.
346	 */
347	export function calculateCategoryInterval(axis: Axis, ctx: AxisLabelsComputingContext) {
348	    const kind = ctx.kind;
349	
350	    const params = fetchAutoCategoryIntervalCalculationParams(axis);
351	    const labelFormatter = makeLabelFormatter(axis);
352	    const rotation = (params.axisRotate - params.labelRotate) / 180 * Math.PI;
353	
354	    const ordinalScale = axis.scale as OrdinalScale;
355	    const ordinalExtent = ordinalScale.getExtent();
356	    // Providing this method is for optimization:
357	    // avoid generating a long array by `getTicks`
358	    // in large category data case.
359	    const tickCount = ordinalScale.count();
360	
361	    if (ordinalExtent[1] - ordinalExtent[0] < 1) {
362	        return 0;
363	    }
364	
365	    let step = 1;
366	    // Simple optimization. Arbitrary value.
367	    const maxCount = 40;
368	    if (tickCount > maxCount) {
369	        step = Math.max(1, Math.floor(tickCount / maxCount));
370	    }
371	    let tickValue = ordinalExtent[0];
372	    const unitSpan = axis.dataToCoord(tickValue + 1) - axis.dataToCoord(tickValue);
373	    const unitW = Math.abs(unitSpan * Math.cos(rotation));
374	    const unitH = Math.abs(unitSpan * Math.sin(rotation));
375	
376	    let maxW = 0;
377	    let maxH = 0;
378	
379	    // Caution: Performance sensitive for large category data.
380	    // Consider dataZoom, we should make appropriate step to avoid O(n) loop.
381	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
382	        let width = 0;
383	        let height = 0;
384	
385	        // Not precise, do not consider align and vertical align
386	        // and each distance from axis line yet.
387	        const rect = textContain.getBoundingRect(
388	            labelFormatter({ value: tickValue }), params.font, 'center', 'top'
389	        );
390	        // Magic number
391	        width = rect.width * 1.3;
392	        height = rect.height * 1.3;
393	
394	        // Min size, void long loop.
395	        maxW = Math.max(maxW, width, 7);
396	        maxH = Math.max(maxH, height, 7);
397	    }
398	
399	    let dw = maxW / unitW;
400	    let dh = maxH / unitH;
401	    // 0/0 is NaN, 1/0 is Infinity.
402	    isNaN(dw) && (dw = Infinity);
403	    isNaN(dh) && (dh = Infinity);
404	    const interval = Math.max(0, Math.floor(Math.min(dw, dh)));
405	
406	    if (kind === AxisTickLabelComputingKind.estimate) {
407	        // In estimate kind, the inteval likely varies, thus do not erase the cache.
408	        ctx.out.noPxChangeTryDetermine.push(
409	            zrUtil.bind(calculateCategoryIntervalTryDetermine, null, axis, interval, tickCount)
410	        );
411	        return interval;
412	    }
413	
414	    const lastInterval = calculateCategoryIntervalDealCache(axis, interval, tickCount);
415	    return lastInterval != null ? lastInterval : interval;
416	}
417	
418	function calculateCategoryIntervalTryDetermine(
419	    axis: Axis, interval: number, tickCount: number
420	): boolean {
421	    return calculateCategoryIntervalDealCache(axis, interval, tickCount) == null;
422	}
423	
424	// Return the lastInterval if need to use it, otherwise return NullUndefined and save cache.
425	function calculateCategoryIntervalDealCache(
426	    axis: Axis, interval: number, tickCount: number
427	): number | NullUndefined {
428	    const cache = modelInner(axis.model);
429	    const axisExtent = axis.getExtent();
430	    const lastAutoInterval = cache.lastAutoInterval;
431	    const lastTickCount = cache.lastTickCount;
432	    // Use cache to keep interval stable while moving zoom window,
433	    // otherwise the calculated interval might jitter when the zoom
434	    // window size is close to the interval-changing size.
435	    // For example, if all of the axis labels are `a, b, c, d, e, f, g`.
436	    // The jitter will cause that sometimes the displayed labels are
437	    // `a, d, g` (interval: 2) sometimes `a, c, e`(interval: 1).
438	    if (lastAutoInterval != null
439	        && lastTickCount != null
440	        && Math.abs(lastAutoInterval - interval) <= 1
441	        && Math.abs(lastTickCount - tickCount) <= 1
442	        // Always choose the bigger one, otherwise the critical
443	        // point is not the same when zooming in or zooming out.
444	        && lastAutoInterval > interval
445	        // If the axis change is caused by chart resize, the cache should not
446	        // be used. Otherwise some hidden labels might not be shown again.
447	        && cache.axisExtent0 === axisExtent[0]
448	        && cache.axisExtent1 === axisExtent[1]
449	    ) {
450	        return lastAutoInterval;
451	    }
452	    // Only update cache if cache not used, otherwise the
453	    // changing of interval is too insensitive.
454	    else {
455	        cache.lastTickCount = tickCount;
456	        cache.lastAutoInterval = interval;
457	        cache.axisExtent0 = axisExtent[0];
458	        cache.axisExtent1 = axisExtent[1];
459	    }
460	}
