549	// When interval is function, the result `false` means ignore the tick.
550	// It is time consuming for large category data.
551	function makeLabelsByCustomizedCategoryInterval(
552	    axis: Axis, categoryInterval: CategoryIntervalCb
553	): AxisLabelInfoDetermined[];
554	function makeLabelsByCustomizedCategoryInterval(
555	    axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick: false
556	): AxisLabelInfoDetermined[];
557	function makeLabelsByCustomizedCategoryInterval(
